// List all configured remotes
// Run: git remote -v
// Output shows:
// origin  https://github.com/yourname/spring-api.git (fetch)
// origin  https://github.com/yourname/spring-api.git (push)

// Add a new remote called 'upstream' for the original project
// Command: git remote add upstream https://github.com/company/spring-api.git

// View details about the origin remote
// Command: git remote show origin

// Rename 'origin' to 'myfork'
// Command: git remote rename origin myfork

// Remove a remote
// Command: git remote remove upstream

// Fetch changes from a specific remote
// Command: git fetch upstream

// Push your feature-login branch to origin
// Command: git push origin feature-login

// Clone a Spring Boot project
git clone https://github.com/company/ecommerce-api.git
// Git performs these operations automatically:

// 1. Creates directory 'ecommerce-api'
// 2. Initializes .git repository
// 3. Adds remote: origin -> https://github.com/company/ecommerce-api.git
// 4. Fetches all branches and commits
// 5. Sets up tracking: local main tracks origin/main
// 6. Checks out main branch into working directory

cd ecommerce-api

// Verify the remote was configured
git remote -v
// origin  https://github.com/company/ecommerce-api.git (fetch)
// origin  https://github.com/company/ecommerce-api.git (push)

// Check tracking relationship
git branch -vv
// * main abc1234 [origin/main] Initial commit

// Shallow clone - only fetches latest commit
git clone --depth 1 https://github.com/company/large-project.git
// Much faster, but no history available

// Clone specific branch only
git clone -b feature-payments https://github.com/company/api.git

// Clone a repository - main automatically tracks origin/main
git clone https://github.com/company/order-service.git
cd order-service

// Check tracking relationships
git branch -vv
// Output: * main abc1234 [origin/main] Latest commit message

// Create a new feature branch
git checkout -b feature-payment-gateway

// First push requires setting upstream with -u flag
git push -u origin feature-payment-gateway
// This creates the remote branch AND sets up tracking

// Now simple commands work without specifying remote
git push  // pushes to origin/feature-payment-gateway
git pull  // pulls from origin/feature-payment-gateway

// View which remote branch your current branch tracks
git status
// Output: On branch feature-payment-gateway
// Your branch is up to date with 'origin/feature-payment-gateway'.

// Set tracking for existing branch without pushing
git branch --set-upstream-to=origin/feature-payment-gateway
